from .processor import current_events


def current_position(batch):
    selected = current_events(batch['deliveries'], batch['period']['as_of'])
    captures = {identity: value for (kind, identity), value in selected.items() if kind == 'capture'}
    merchants = set(batch['period']['merchants'])
    for capture in captures.values():
        eligible = capture['eligible']
        if not isinstance(eligible, list) or not eligible or any(m not in merchants for m in eligible):
            raise CloseError('Capture must have eligible declared merchants')
    refunds = defaultdict(int)
    for (kind, identity), value in selected.items():
        if kind == 'refund':
            if value['capture'] not in captures:
                raise CloseError('Refund has no current capture')
            refunds[value['capture']] += value['amount_cents']
    for identity, amount in refunds.items():
        if amount > captures[identity]['amount_cents']:
            raise CloseError('Selected refunds exceed capture gross: ' + identity)
    fixed = {}
    for posting in batch['journal']:
        if posting['signed'] and posting['closed']:
            capture, merchant = posting['capture'], posting['merchant']
            if capture not in captures or merchant not in captures[capture]['eligible']:
                raise CloseError('Posted capture identity differs')
            if capture in fixed and fixed[capture] != merchant:
                raise CloseError('Conflicting posted merchants')
            fixed[capture] = merchant
    return captures, dict(refunds), fixed

from .errors import CloseError


def current_events(deliveries, as_of):
    """Select whole final revisions without giving delivery order authority."""
    seen = {}
    current = {}
    for row in deliveries:
        if type(row['known']) is not int:
            raise CloseError('Processor known time must be an integer')
        if row['known'] > as_of:
            continue
        if row['kind'] not in ('capture', 'refund'):
            raise CloseError('Unknown processor record kind')
        if type(row['revision']) is not int or row['revision'] <= 0:
            raise CloseError('Processor revision must be a positive integer')
        if type(row['final']) is not bool:
            raise CloseError('Processor final flag must be a boolean')
        amount = row['amount_cents']
        if type(amount) is not int or amount < 0:
            raise CloseError('Processor amounts must be nonnegative integer cents')
        if row['kind'] == 'capture' and amount == 0:
            raise CloseError('Capture amount must be positive')
        identity = (row['kind'], row['id'], row['revision'])
        value = {k: v for k, v in row.items() if k != 'event_id'}
        # Check every visible revision, including drafts and superseded finals.
        if identity in seen and seen[identity] != value:
            raise CloseError('Conflicting processor revision')
        seen[identity] = value
        if row['final']:
            entity = (row['kind'], row['id'])
            if entity not in current or row['revision'] > current[entity]['revision']:
                current[entity] = value
    return current

from itertools import permutations

import pytest

from period_close.errors import CloseError
from period_close.processor import current_events


def delivery(record_kind='capture', **changes):
    row = {
        'event_id': 'delivery', 'kind': record_kind, 'id': 'entity',
        'revision': 1, 'known': 1, 'final': True, 'amount_cents': 500,
    }
    row.update({'eligible': ['A']} if record_kind == 'capture' else {'capture': 'payment'})
    row.update(changes)
    return row


@pytest.mark.parametrize('kind', ['capture', 'refund'])
def test_highest_visible_final_revision_wins_in_every_delivery_order(kind):
    rows = [
        delivery(kind, revision=1, known=9),
        delivery(kind, revision=2, known=4, amount_cents=300),
        delivery(kind, revision=3, known=8, final=False, amount_cents=900),
        delivery(kind, revision=4, known=11, amount_cents=100),
    ]
    for order in permutations(rows):
        selected = current_events(order, as_of=10)
        assert selected[(kind, 'entity')]['revision'] == 2
        assert selected[(kind, 'entity')]['amount_cents'] == 300


@pytest.mark.parametrize('kind', ['capture', 'refund'])
def test_old_revision_replay_and_new_envelope_id_do_not_change_position(kind):
    old = delivery(kind)
    new = delivery(kind, revision=2, known=2, amount_cents=200)
    expected = current_events([old, new], as_of=10)
    replay = [old, new, dict(new, event_id='another-delivery'), old, old]
    assert current_events(replay, as_of=10) == expected


def test_entity_and_kind_are_monetary_identity_not_event_id():
    rows = [delivery(), delivery('refund'), delivery(id='another-capture')]
    assert set(current_events(rows * 2, as_of=10)) == {
        ('capture', 'entity'), ('refund', 'entity'), ('capture', 'another-capture'),
    }


@pytest.mark.parametrize('kind', ['capture', 'refund'])
@pytest.mark.parametrize('state', ['current', 'superseded', 'draft'])
def test_conflicting_visible_revision_is_rejected_even_when_not_selected(kind, state):
    original = delivery(kind, final=(state != 'draft'))
    conflict = dict(original, event_id='different-envelope', amount_cents=400)
    rows = [original, conflict]
    if state != 'current':
        rows.append(delivery(kind, revision=2, amount_cents=200))
    for order in permutations(rows):
        with pytest.raises(CloseError, match='Conflicting processor revision'):
            current_events(order, as_of=10)


@pytest.mark.parametrize('change', [
    {'known': 2}, {'final': False}, {'eligible': ['B']},
])
def test_conflicts_include_non_amount_payload_fields(change):
    original = delivery()
    with pytest.raises(CloseError, match='Conflicting processor revision'):
        current_events([original, dict(original, **change)], as_of=10)


def test_cutoff_is_inclusive_and_future_conflicts_are_not_visible():
    current = delivery(known=10)
    future = delivery(revision=2, known=11)
    rows = [current, future, dict(future, amount_cents=200)]
    assert current_events(rows, as_of=10)[('capture', 'entity')]['revision'] == 1
    with pytest.raises(CloseError, match='Conflicting processor revision'):
        current_events(rows, as_of=11)


def test_draft_only_entity_has_no_current_position():
    assert current_events([delivery(final=False)], as_of=10) == {}


@pytest.mark.parametrize('kind,change', [
    ('capture', {'amount_cents': 0}),
    ('capture', {'amount_cents': -1}),
    ('refund', {'amount_cents': -1}),
    ('capture', {'amount_cents': 1.5}),
    ('refund', {'amount_cents': True}),
    ('capture', {'revision': 0}),
    ('refund', {'revision': 1.5}),
    ('capture', {'known': 1.5}),
    ('capture', {'final': 'true'}),
    ('capture', {'kind': 'adjustment'}),
])
def test_invalid_processor_values_fail_closed(kind, change):
    with pytest.raises(CloseError):
        current_events([delivery(kind, **change)], as_of=10)


def test_zero_refund_replacement_is_retained():
    selected = current_events([
        delivery('refund', revision=2, amount_cents=0), delivery('refund'),
    ], as_of=10)
    assert selected[('refund', 'entity')]['amount_cents'] == 0
